// Book4air Live Data — Fixed Departure fares for agent 24 (BOOK).
//
// Only Calicut/Kochi/Trivandrum origins are in scope, per the user: the
// site's own "Available Sectors" list covers many more Indian cities Zamra
// does not sell ex-CCJ/COK/TRV flights for.
//
// The fetch runs inline in one Code node rather than as separate HTTP
// Request nodes: eapi.book4air.com needs a fresh Bearer token every run
// (its JWT actually expires, unlike FlyCreative's oddly-persistent static
// session cookie), and keeping auth + all four sector calls in one place
// avoids threading that token through per-item expressions across nodes.
// The API key below is not a secret — it ships in book4air's own public
// client-side JS for anyone visiting the site to use directly.

const BASE_URL = 'https://eapi.book4air.com';
const API_KEY = '0E6E4463-F585-4300-997C-CF5CB8A7E0C2';
const AGENT_ID = '24';

const SECTORS = [
  { origin: 'CCJ', destination: 'DXB' },
  { origin: 'COK', destination: 'DXB' },
  { origin: 'COK', destination: 'KWI' },
  { origin: 'TRV', destination: 'KWI' },
];

const authRes = await this.helpers.httpRequest({
  method: 'POST',
  url: `${BASE_URL}/api/Authenticate`,
  headers: { 'Content-Type': 'application/json' },
  body: { apiKey: API_KEY },
  json: true,
});

const rawToken = authRes && (authRes.token || (authRes.data && authRes.data.token));
if (!rawToken) {
  throw new Error('Book4air auth did not return a token: ' + JSON.stringify(authRes).slice(0, 300));
}
const token = rawToken.startsWith('Bearer ') ? rawToken : `Bearer ${rawToken}`;

const firebaseData = [];

for (const { origin, destination } of SECTORS) {
  const datesRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `${BASE_URL}/api/Sector/available-dates-with-deatils`,
    headers: { 'Content-Type': 'application/json', 'Authorization': token },
    body: { origin, destination },
    json: true,
  });

  const dates = (datesRes && datesRes.data && Array.isArray(datesRes.data.data)) ? datesRes.data.data : [];
  if (dates.length === 0) continue; // no fixed-departure inventory on this sector right now

  // Airline/flight number/times/baggage do not vary by date for a fixed
  // departure block (confirmed 2026-09-07 across several dates per sector),
  // so one `search` call for the first available date covers the whole run.
  const searchRes = await this.helpers.httpRequest({
    method: 'POST',
    url: `${BASE_URL}/api/Sector/search`,
    headers: { 'Content-Type': 'application/json', 'Authorization': token },
    body: { origin, destination, date: dates[0].availableDate, pax: 1 },
    json: true,
  });

  const flight = (searchRes && searchRes.data && Array.isArray(searchRes.data.search)) ? searchRes.data.search[0] : null;
  if (!flight || !flight.airline) continue; // nothing bookable right now — skip rather than guess

  for (const row of dates) {
    if (!row.availableDate || !row.price) continue;
    firebaseData.push({
      agent_id: AGENT_ID,
      sector_code: `${origin} ${destination}`,
      flight_code: flight.airline,
      date: row.availableDate,
      time_start: flight.deparTime || '',
      time_end: flight.arrTime || '',
      baggage: flight.checkInWeight || '',
      extra_baggage: flight.cabinWeight || '',
      sp_rate: row.price,
      // Commission and the final selling price are derived server-side from
      // agents.commission (ingestFaresFromN8n) — never send them here.
      show: row.availableSeats > 0 ? 'yes' : 'no',
    });
  }
}

return [{ json: { firebaseData } }];
